package com.hibernate.ecommerce.service;import com.hibernate.ecommerce.dto.OrderDTO;import com.hibernate.ecommerce.dto.OrderdetailsDTO;import com.hibernate.ecommerce.exception.ResourceNotFoundException;import com.hibernate.ecommerce.mapper.OrderMapper;import com.hibernate.ecommerce.mapper.OrderdetailsMapper;import com.hibernate.ecommerce.model.*;import com.hibernate.ecommerce.repository.ClientRepository;import com.hibernate.ecommerce.repository.OrderRepository;import com.hibernate.ecommerce.repository.ProductRepository;import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import java.util.ArrayList;import java.util.List;@Servicepublic class OrderService implements IOrderService {    private final OrderRepository orderRepository;    private final ClientRepository clientRepository;    private final ProductRepository productRepository;    public OrderService(OrderRepository orderRepository, ClientRepository clientRepository, ProductRepository productRepository) {        this.orderRepository = orderRepository;        this.clientRepository = clientRepository;        this.productRepository = productRepository;    }    @Override    @Transactional    public OrderDTO addOrder(OrderDTO dto) {        if(dto == null ) return null;        Client searchClient = clientRepository.findById(dto.getClientId())                .orElseThrow(() -> new RuntimeException("The client by id: "+dto.getClientId()+" are not exists"));        Order order = Order.builder()                .state(state.PENDIENTE)                .client(searchClient)                .build();        List<Orderdetails> orderdetailsList = new ArrayList<>();        for(OrderdetailsDTO orderdetailsDTO : dto.getOrderdetails()){            Product product = productRepository.findById(orderdetailsDTO.getProductId())                    .orElseThrow(() -> new RuntimeException("The product by id: "+orderdetailsDTO.getProductId()+" are not exists"));            if(product.getStock() >= orderdetailsDTO.getQuantity()){                Orderdetails orderdetails = OrderdetailsMapper.toEntity(orderdetailsDTO, order, product);                orderdetailsList.add(orderdetails);                product.setStock(product.getStock()-orderdetailsDTO.getQuantity());            }else{                throw new ResourceNotFoundException("Stock insufficient");            }        }        order.setOrderdetails(orderdetailsList);        Order save = orderRepository.save(order);        return OrderMapper.toDTO(save);    }    @Override    public OrderDTO findOrderById(Long id) {        Order search = orderRepository.findById(id)                .orElseThrow(() -> new ResourceNotFoundException("The order by id: "+id+" are not exists"));        return OrderMapper.toDTO(search);    }    @Override    public List<OrderDTO> findOrderByClient(Long id, state state) {        if(id == null){            throw new IllegalArgumentException("Client ID must not be null");        }        List<Order> orders = orderRepository.findByClientIdAndOptionalState(id, state);        return orders.stream()                .map(OrderMapper::toDTO)                .toList();    }    @Override    @Transactional    public OrderDTO changeState(OrderDTO dto) {        if(dto == null){            throw new IllegalArgumentException("The order must not be null");        }        if (dto.getState() == null) {            throw new IllegalArgumentException("State cannot be null");        }        Order searchOrder = orderRepository.findById(dto.getId())                .orElseThrow(() -> new ResourceNotFoundException("The order by id: "+dto.getId()+" are not exists"));        if(searchOrder.getState() == state.PENDIENTE && dto.getState() == state.CANCELADO){            searchOrder.setState(dto.getState());            for(Orderdetails orderdetails : searchOrder.getOrderdetails()){                orderdetails.getProduct().setStock(orderdetails.getProduct().getStock() + orderdetails.getQuantity());            }        }else if(searchOrder.getState() == state.PENDIENTE && dto.getState() == state.ENVIADO){            searchOrder.setState(dto.getState());        }else if(searchOrder.getState() == state.ENVIADO && dto.getState() == state.ENTREGADO){            searchOrder.setState(dto.getState());        }else{            throw new IllegalStateException("Insert a new valid state");        }        Order save = orderRepository.save(searchOrder);        return OrderMapper.toDTO(save);    }    @Override    public void deleteOrder(Long id) {        Order searchOrder = orderRepository.findById(id)                .orElseThrow(() -> new ResourceNotFoundException("The order by id: "+id+" are not exists"));        if(searchOrder.getState() == state.PENDIENTE){            orderRepository.delete(searchOrder);            for(Orderdetails orderdetails : searchOrder.getOrderdetails()){                orderdetails.getProduct().setStock(orderdetails.getProduct().getStock() + orderdetails.getQuantity());            }        }else if(searchOrder.getState() == state.CANCELADO){            orderRepository.delete(searchOrder);            for(Orderdetails orderdetails : searchOrder.getOrderdetails()){                orderdetails.getProduct().setStock(orderdetails.getProduct().getStock() + orderdetails.getQuantity());            }        }else{            throw new IllegalArgumentException("The order status must be pending or canceled");        }    }}